/**
 * Stage-level views of a plan run: the stage run detail page and the per-stage
 * progression the plan run detail shows for each `protoStage` value.
 */
import {
  type Scenario,
  approveButton,
  expect,
  main,
  protoUrl,
  stageStatus,
  test,
} from "../support";

test.describe("Stage run detail", () => {
  test("a finished stage shows timestamps, agent activity and commits", async ({
    page,
  }) => {
    // Run 1, stage 1 (Prepare proposal). Its commit hash is generated by the
    // mock (mockRunHash(1, 0) = "007a69cafe", shown as 8 characters).
    await page.goto(
      protoUrl("/plan-runs/1/stages/1", { scenario: "actionRequired" })
    );
    for (const term of ["Started", "Completed"])
      await expect(
        page.getByRole("term").filter({ hasText: term })
      ).toBeVisible();
    await expect(
      page.getByRole("heading", { name: "Activities" })
    ).toBeVisible();
    await expect(page.getByText(/Starting "Prepare proposal"/)).toBeVisible();
    await expect(page.getByRole("heading", { name: "Commits" })).toBeVisible();
    await expect(page.getByText("007a69ca")).toBeVisible();
    await expect(
      page.getByText("Agent communication logs will appear here")
    ).toHaveCount(0);
  });

  test("a pending stage keeps empty timestamps and has no activity or commits", async ({
    page,
  }) => {
    await page.goto(
      protoUrl("/plan-runs/2/stages/5", { scenario: "actionRequired" })
    );
    for (const term of ["Started", "Completed"])
      await expect(
        page.getByRole("term").filter({ hasText: term })
      ).toBeVisible();
    await expect(
      page.getByRole("definition").filter({ hasText: /^—$/ })
    ).toHaveCount(2);
    await expect(page.getByRole("heading", { name: "Activities" })).toHaveCount(
      0
    );
    await expect(page.getByRole("heading", { name: "Commits" })).toHaveCount(0);
  });

  test("a running stage streams its first progress message", async ({
    page,
  }) => {
    await page.goto(protoUrl("/plan-runs/1", { scenario: "running" }));
    await expect(
      page.getByText(/initializing analysis environment/)
    ).toBeVisible();
  });
});

test.describe("Plan run stage progression (Run #1, three stages)", () => {
  const stages = ["Prepare proposal", "Migrate", "Validate"];
  // [scenario, protoStage, expected status per stage]
  const cases: [Scenario, number, string[]][] = [
    ["running", 1, ["Running", "Pending", "Pending"]],
    ["running", 2, ["Succeeded", "Running", "Pending"]],
    ["actionRequired", 1, ["Awaiting approval", "Pending", "Pending"]],
    ["actionRequired", 2, ["Succeeded", "Awaiting approval", "Pending"]],
    ["failed", 1, ["Failed", "Pending", "Pending"]],
    ["failed", 2, ["Succeeded", "Failed", "Pending"]],
    ["completed", 1, ["Succeeded", "Succeeded", "Succeeded"]],
  ];

  for (const [scenario, stage, expected] of cases) {
    test(`${scenario} at stage ${stage}: ${expected.join(", ")}`, async ({
      page,
    }) => {
      await page.goto(protoUrl("/plan-runs/1", { scenario, stage }));
      for (const [index, name] of stages.entries())
        await expect(stageStatus(page, name)).toHaveText(expected[index]);
      if (scenario === "actionRequired")
        await expect(approveButton(page)).toBeVisible();
      if (scenario === "failed")
        await expect(
          main(page).getByText("Unable to resolve dependency tree").first()
        ).toBeVisible();
    });
  }

  test("an earlier succeeded stage keeps its commits while collapsed", async ({
    page,
  }) => {
    await page.goto(
      protoUrl("/plan-runs/1", { scenario: "running", stage: 2 })
    );
    await expect(
      page.getByText(/apply migration changes/).first()
    ).toBeAttached();
  });
});
